import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const port = Number(process.env.PORT ?? 8080);
const databasePath = process.env.DB_PATH ?? 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK(length(trim(name)) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK(length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
`);
// Existing databases retain their IDs and tasks when archive support is added.
if (!database.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
}
// Default priorities also apply to tasks created before priority support.
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
}
// Project defaults affect future task creation only; existing tasks retain their priorities.
if (!database.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_priority IN ('Low', 'Normal', 'High'))");
}
// Optional calendar dates start empty without changing existing task data.
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
const taskPriorities = ['Low', 'Normal', 'High'];
const listProjects = database.prepare(`
  SELECT projects.id, projects.name, projects.archived,
    COUNT(tasks.id) AS total, COALESCE(SUM(tasks.completed), 0) AS completed
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
  WHERE projects.archived = ?
  GROUP BY projects.id ORDER BY projects.id
`);
const findProject = database.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?');
const updateDefaultPriority = database.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY id');
const insertTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const findTask = database.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');
const updateTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');

function validDueDate(value) {
  if (value === '') return true;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= daysInMonth[month - 1];
}

function projectFilter(value) {
  return value === 'archived' ? 'archived' : 'active';
}

function taskFilter(value) {
  return ['open', 'completed'].includes(value) ? value : 'all';
}

function taskFilters(parameters) {
  const priority = parameters.get('priorityFilter');
  return {
    completion: taskFilter(parameters.get('filter')),
    priority: taskPriorities.includes(priority) ? priority : 'All',
  };
}

function projectUrl(projectId, filters) {
  const parameters = new URLSearchParams();
  if (filters.completion !== 'all') parameters.set('filter', filters.completion);
  if (filters.priority !== 'All') parameters.set('priorityFilter', filters.priority);
  const query = parameters.toString();
  return `/projects/${projectId}${query ? `?${query}` : ''}`;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f4f6fa; color: #19283c; font: 16px system-ui, sans-serif; }
    main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce2eb; border-radius: 12px; }
    h1 { margin-top: 0; font-size: 32px; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input { min-width: 0; width: 100%; padding: 11px; border: 1px solid #8996a8; border-radius: 6px; font: inherit; }
    select { padding: 11px; font: inherit; border: 1px solid #8996a8; border-radius: 6px; }
    .project-rename, .task-create, .task-filter { margin-top: 28px; }
    .task-row { padding: 18px 0; border-top: 1px solid #dce2eb; }
    .task-completion label { display: flex; align-items: center; gap: 12px; margin: 0; overflow-wrap: anywhere; }
    .task-completion input { width: 20px; height: 20px; flex-shrink: 0; }
    .task-rename, .task-priority, .task-due-date { margin-top: 16px; }
    button { padding: 11px 16px; border: 0; border-radius: 6px; background: #244fba; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:disabled { opacity: 0.5; cursor: default; }
    button:hover { background: #193b91; }
    :focus-visible { outline: 3px solid #e99f1b; outline-offset: 3px; }
    .create-controls { display: flex; gap: 12px; }
    .create-controls button { flex-shrink: 0; }
    .project-list { list-style: none; padding: 0; margin: 28px 0 0; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 18px 0; border-top: 1px solid #dce2eb; }
    .project-row > div { min-width: 0; }
    .project-row span { overflow-wrap: anywhere; min-width: 0; }
    .project-row form { flex-shrink: 0; }
    .project-actions { display: flex; gap: 8px; flex-wrap: wrap; }
    .project-summary { display: block; margin-top: 6px; color: #556478; }
    [role="alert"] { color: #a21c20; margin: 16px 0; }
    .empty { color: #556478; margin-top: 28px; }
    @media (max-width: 560px) { main { margin: 20px 12px; padding: 24px; } .create-controls { flex-direction: column; } .project-row { flex-wrap: wrap; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function projectsPage(error = '', filter = 'active') {
  const projects = listProjects.all(filter === 'archived' ? 1 : 0);
  return page('Projects', `
    <h1>Workboard</h1>
    <form method="post" action="/projects">
      <input type="hidden" name="filter" value="${filter}">
      <label for="project-name">Project name</label>
      <div class="create-controls">
        <input id="project-name" name="name" type="text"${error ? ' aria-invalid="true" aria-describedby="project-error"' : ''}>
        <button type="submit">Create project</button>
      </div>
    </form>
    ${error ? `<p id="project-error" role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="task-filter" method="get" action="/">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${[['active', 'Active'], ['archived', 'Archived']].map(([value, label]) =>
          `<option value="${value}"${filter === value ? ' selected' : ''}>${label}</option>`).join('')}
      </select>
    </form>
    ${projects.length ? `<ul class="project-list" aria-label="Projects">${projects.map(project => `
      <li class="project-row" data-testid="project-row">
        <div><span>${escapeHtml(project.name)}</span>
          <span class="project-summary" data-testid="project-summary">${project.completed}/${project.total} completed</span>
        </div>
        <div class="project-actions">
          <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
          <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}">
            <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
          </form>
        </div>
      </li>`).join('')}</ul>` : '<p class="empty">No projects yet.</p>'}
  `);
}

function projectPage(project, filters = { completion: 'all', priority: 'All' }, error = '', renameError = '', taskError = null) {
  const { completion: filter, priority: priorityFilter } = filters;
  const filterFields = `<input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">`;
  const tasks = listTasks.all(project.id).filter(task =>
    (filter === 'all' || Boolean(task.completed) === (filter === 'completed')) &&
    (priorityFilter === 'All' || task.priority === priorityFilter));
  return page(project.name, `
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form method="get" action="/"><button type="submit">Projects</button></form>
    <form class="project-rename" method="post" action="/projects/${project.id}/rename">
      ${filterFields}
      <label for="new-project-name">New project name</label>
      <div class="create-controls">
        <input id="new-project-name" name="name" type="text"${project.archived ? ' disabled' : ''}${renameError ? ' aria-invalid="true" aria-describedby="rename-error"' : ''}>
        <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
      </div>
    </form>
    ${renameError ? `<p id="rename-error" role="alert">${escapeHtml(renameError)}</p>` : ''}
    <form class="task-priority" method="post" action="/projects/${project.id}/default-priority">
      ${filterFields}
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
        ${taskPriorities.map(priority =>
          `<option value="${priority}"${project.default_priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
      </select>
    </form>
    <form class="task-create" method="post" action="/projects/${project.id}/tasks">
      ${filterFields}
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" name="title" type="text"${error ? ' aria-invalid="true" aria-describedby="task-error"' : ''}>
        <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
      </div>
    </form>
    ${error ? `<p id="task-error" role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="task-filter" method="get" action="/projects/${project.id}">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${[['all', 'All'], ['open', 'Open'], ['completed', 'Completed']].map(([value, label]) =>
          `<option value="${value}"${filter === value ? ' selected' : ''}>${label}</option>`).join('')}
      </select>
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter" name="priorityFilter" onchange="this.form.requestSubmit()">
        ${['All', ...taskPriorities].map(priority =>
          `<option value="${priority}"${priorityFilter === priority ? ' selected' : ''}>${priority}</option>`).join('')}
      </select>
    </form>
    ${tasks.length ? `<ul class="project-list" aria-label="Tasks">${tasks.map(task => `
      <li class="task-row" data-testid="task-row">
        <form class="task-completion" method="post" action="/projects/${project.id}/tasks/${task.id}">
          ${filterFields}
          <label>
            <input type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
            <span>${escapeHtml(task.title)}</span>
          </label>
        </form>
        <form class="task-rename" method="post" action="/projects/${project.id}/tasks/${task.id}/rename">
          ${filterFields}
          <label for="new-task-title-${task.id}">New task title</label>
          <div class="create-controls">
            <input id="new-task-title-${task.id}" name="title" type="text"${project.archived ? ' disabled' : ''}${taskError?.id === task.id && taskError.field === 'title' ? ` aria-invalid="true" aria-describedby="task-rename-error-${task.id}"` : ''}>
            <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
          </div>
        </form>
        ${taskError?.id === task.id && taskError.field === 'title' ? `<p id="task-rename-error-${task.id}" role="alert">${escapeHtml(taskError.message)}</p>` : ''}
        <form class="task-priority" method="post" action="/projects/${project.id}/tasks/${task.id}/priority">
          ${filterFields}
          <label for="task-priority-${task.id}">Task priority</label>
          <select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
            ${taskPriorities.map(priority =>
              `<option value="${priority}"${task.priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
          </select>
        </form>
        <form class="task-due-date" method="post" action="/projects/${project.id}/tasks/${task.id}/due-date">
          ${filterFields}
          <label for="task-due-date-${task.id}">Task due date</label>
          <div class="create-controls">
            <input id="task-due-date-${task.id}" name="dueDate" type="text" value="${escapeHtml(task.due_date)}"${project.archived ? ' disabled' : ''}${taskError?.id === task.id && taskError.field === 'dueDate' ? ` aria-invalid="true" aria-describedby="task-due-date-error-${task.id}"` : ''}>
            <button type="submit"${project.archived ? ' disabled' : ''}>Save due date</button>
          </div>
        </form>
        ${taskError?.id === task.id && taskError.field === 'dueDate' ? `<p id="task-due-date-error-${task.id}" role="alert">${escapeHtml(taskError.message)}</p>` : ''}
      </li>`).join('')}</ul>` : '<p class="empty">No matching tasks.</p>'}
  `);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 1024 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const { pathname, searchParams } = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (request.method === 'GET' && pathname === '/') {
      sendHtml(response, 200, projectsPage('', projectFilter(searchParams.get('filter'))));
      return;
    }
    if (request.method === 'POST' && pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') ?? '').trim();
      if (!name) {
        sendHtml(response, 400, projectsPage('Project name is required', projectFilter(form.get('filter'))));
        return;
      }
      insertProject.run(name);
      redirect(response, '/');
      return;
    }
    const defaultPriorityMatch = /^\/projects\/([1-9]\d*)\/default-priority$/.exec(pathname);
    if (request.method === 'POST' && defaultPriorityMatch) {
      const id = Number(defaultPriorityMatch[1]);
      const form = await readForm(request);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (project) {
        const filters = taskFilters(form);
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filters, 'Archived project cannot be changed'));
          return;
        }
        const priority = form.get('priority');
        if (!taskPriorities.includes(priority)) {
          sendHtml(response, 400, projectPage(project, filters, 'Default task priority must be Low, Normal, or High'));
          return;
        }
        updateDefaultPriority.run(priority, id);
        redirect(response, projectUrl(id, filters));
        return;
      }
    }
    const renameMatch = /^\/projects\/([1-9]\d*)\/rename$/.exec(pathname);
    if (request.method === 'POST' && renameMatch) {
      const id = Number(renameMatch[1]);
      const form = await readForm(request);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (project) {
        const filters = taskFilters(form);
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filters, '', 'Archived project cannot be changed'));
          return;
        }
        const name = (form.get('name') ?? '').trim();
        if (!name) {
          sendHtml(response, 400, projectPage(project, filters, '', 'Project name is required'));
          return;
        }
        renameProject.run(name, id);
        redirect(response, projectUrl(id, filters));
        return;
      }
    }
    const taskRenameMatch = /^\/projects\/([1-9]\d*)\/tasks\/([1-9]\d*)\/rename$/.exec(pathname);
    if (request.method === 'POST' && taskRenameMatch) {
      const projectId = Number(taskRenameMatch[1]);
      const taskId = Number(taskRenameMatch[2]);
      const form = await readForm(request);
      // Read current archive state after the request body has arrived.
      const project = Number.isSafeInteger(projectId) ? findProject.get(projectId) : undefined;
      if (project && Number.isSafeInteger(taskId) && findTask.get(taskId, projectId)) {
        const filters = taskFilters(form);
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filters, 'Archived project cannot be changed'));
          return;
        }
        const title = (form.get('title') ?? '').trim();
        if (!title) {
          sendHtml(response, 400, projectPage(project, filters, '', '', {
            id: taskId, field: 'title', message: 'Task title is required',
          }));
          return;
        }
        renameTask.run(title, taskId, projectId);
        redirect(response, projectUrl(projectId, filters));
        return;
      }
      sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
      return;
    }
    const taskPriorityMatch = /^\/projects\/([1-9]\d*)\/tasks\/([1-9]\d*)\/priority$/.exec(pathname);
    if (request.method === 'POST' && taskPriorityMatch) {
      const projectId = Number(taskPriorityMatch[1]);
      const taskId = Number(taskPriorityMatch[2]);
      const form = await readForm(request);
      const project = Number.isSafeInteger(projectId) ? findProject.get(projectId) : undefined;
      if (project && Number.isSafeInteger(taskId) && findTask.get(taskId, projectId)) {
        const filters = taskFilters(form);
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filters, 'Archived project cannot be changed'));
          return;
        }
        const priority = form.get('priority');
        if (!taskPriorities.includes(priority)) {
          sendHtml(response, 400, projectPage(project, filters, 'Task priority must be Low, Normal, or High'));
          return;
        }
        updateTaskPriority.run(priority, taskId, projectId);
        redirect(response, projectUrl(projectId, filters));
        return;
      }
      sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
      return;
    }
    const taskDueDateMatch = /^\/projects\/([1-9]\d*)\/tasks\/([1-9]\d*)\/due-date$/.exec(pathname);
    if (request.method === 'POST' && taskDueDateMatch) {
      const projectId = Number(taskDueDateMatch[1]);
      const taskId = Number(taskDueDateMatch[2]);
      const form = await readForm(request);
      const project = Number.isSafeInteger(projectId) ? findProject.get(projectId) : undefined;
      if (project && Number.isSafeInteger(taskId) && findTask.get(taskId, projectId)) {
        const filters = taskFilters(form);
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filters, 'Archived project cannot be changed'));
          return;
        }
        const dueDate = (form.get('dueDate') ?? '').trim();
        if (!validDueDate(dueDate)) {
          sendHtml(response, 400, projectPage(project, filters, '', '', {
            id: taskId, field: 'dueDate', message: 'Due date must be a valid YYYY-MM-DD date',
          }));
          return;
        }
        updateTaskDueDate.run(dueDate, taskId, projectId);
        redirect(response, projectUrl(projectId, filters));
        return;
      }
      sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
      return;
    }
    const archiveMatch = /^\/projects\/([1-9]\d*)\/(archive|restore)$/.exec(pathname);
    if (request.method === 'POST' && archiveMatch) {
      const id = Number(archiveMatch[1]);
      if (Number.isSafeInteger(id) && findProject.get(id)) {
        const archived = archiveMatch[2] === 'archive';
        updateArchive.run(archived ? 1 : 0, id);
        redirect(response, archived ? '/' : '/?filter=archived');
        return;
      }
    }
    const match = /^\/projects\/([1-9]\d*)(?:\/tasks(?:\/([1-9]\d*))?)?$/.exec(pathname);
    if (match) {
      const id = Number(match[1]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (project && request.method === 'GET' && pathname === `/projects/${id}`) {
        sendHtml(response, 200, projectPage(project, taskFilters(searchParams)));
        return;
      }
      if (project && request.method === 'POST' && pathname.includes('/tasks')) {
        const form = await readForm(request);
        const filters = taskFilters(form);
        const currentProject = findProject.get(id);
        if (currentProject.archived) {
          sendHtml(response, 403, projectPage(currentProject, filters, 'Archived project cannot be changed'));
          return;
        }
        if (!match[2]) {
          const title = (form.get('title') ?? '').trim();
          if (!title) {
            sendHtml(response, 400, projectPage(project, filters, 'Task title is required'));
            return;
          }
          insertTask.run(id, title, currentProject.default_priority);
        } else {
          const taskId = Number(match[2]);
          if (!Number.isSafeInteger(taskId)) {
            sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
          const result = updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, id);
          if (!result.changes) {
            sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
        }
        redirect(response, projectUrl(id, filters));
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    console.error(error);
    sendHtml(response, error.status ?? 500, page('Error', '<h1>Unable to process request</h1>'));
  }
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    database.close();
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test",
    "check": "node --check server.js && node --check test/projects.test.js"
  }
}
# Workboard

Requires Node.js 22.22.1. Uses built-in HTTP and SQLite with no external dependencies.

Start the application:

```sh
npm start
```

The server binds to `0.0.0.0` on `PORT` (default `8080`). `DB_PATH` selects the persistent SQLite file (default `data/workboard.sqlite`); its parent directory is created automatically.

```sh
PORT=8080 DB_PATH=data/workboard.sqlite npm start
```

Open `/` to create and open projects. `GET /health` returns `{"status":"ok"}`. Project names are trimmed, required, and escaped when rendered. Projects are listed by their persistent creation IDs. Form submissions redirect after successful creation so refreshing the list does not create another project.

Project pages support task creation, completion checkboxes, and All/Open/Completed filters. Task titles are trimmed and required. Tasks belong to their project, and completion persists in SQLite. Filter selections are stored in the page URL; task submissions preserve both current filters. The browser submits completion and filter changes automatically.

The project list starts with Active projects and supports an Archived filter. Archive and restore preserve project IDs, tasks, and completion state. Archived project pages allow task filtering but disable creation and completion changes; the server also rejects these mutations. Each project row shows completed/total counts across all its tasks. Existing databases are migrated automatically, with existing projects remaining active.

Active project pages support renaming with a trimmed, required name. Renaming preserves the project's URL, creation order, tasks, and completion counts. Archived projects disable rename controls and reject rename requests; restoring a project enables renaming again. Names persist across reloads and server restarts.

Each task row supports renaming with a trimmed, required title. Renaming preserves ownership, creation order, completion state, filter membership, and project summaries, while updating the completion checkbox label. Archived projects disable task rename controls and reject rename requests. Restoring a project enables task renaming again. Task titles persist across reloads and process restarts.

Each task row has a Task priority selector with Low, Normal, and High options. Existing tasks default to Normal when migrated; new tasks inherit their project's saved default. Priority changes persist independently without changing task titles, completion, ownership, order, filters, or project summaries. Renaming preserves priority. Archived projects disable priority selectors and reject priority changes; restoration enables them with their saved values. Invalid priority values are rejected without modifying data.

Each project page also has a Priority filter with All, Low, Normal, and High options. Both task filters start at All when opening a project from the list. Tasks must match both selected filters and retain creation order. Changing either filter preserves the other selection. Completion and priority edits immediately re-evaluate the rows after submission; renaming retains filter selections. Filters remain enabled in archived projects. Filtering never changes saved tasks or project summaries.

Each project page has a Default task priority selector with Low, Normal, and High options, initially Normal. Changes affect only subsequent task creation in that project and preserve existing tasks, both selected filters, and completion summaries. Defaults persist independently across reloads, restarts, project renaming, archive, and restore. Archived projects display a disabled selector and reject default changes on the server. Existing databases are migrated without changing task priorities or project identity.

Each task row has a Task due date textbox and Save due date button. Dates are optional: empty or whitespace-only input clears the saved date. Other values are trimmed and must be real Gregorian calendar dates in YYYY-MM-DD format with years 0001–9999. Validation uses calendar arithmetic without timezone conversion; invalid input leaves the saved date and other task data unchanged. Due dates persist independently through renaming, reloads, restarts, archive, and restore. Saving preserves both filters and completion summaries. Archived projects disable due-date controls and reject date changes on the server. Existing tasks migrate to empty dates.

Run syntax checks and integration tests:

```sh
npm run check
npm test
```

The integration tests start real server processes on ephemeral ports and verify validation, creation order, escaping, task filtering, project isolation, completion updates, archive/restore, renaming without identity changes, independent task priorities, all combined priority/completion filters, filter retention during edits, completion summaries, archived mutation rejection, due-date calendar boundaries and clearing, database migration, and restart persistence using temporary databases that are removed afterward.
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { test } from 'node:test';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', chunk => { errors += chunk; });
  const url = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', error => { clearTimeout(timeout); reject(error); });
    child.once('exit', code => {
      clearTimeout(timeout);
      reject(new Error(`Server exited with ${code}: ${errors}`));
    });
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = /listening on port (\d+)/.exec(output);
      if (match) {
        clearTimeout(timeout);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    url,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('projects and tasks validate, filter, isolate, and persist across restarts', async () => {
  const directory = await mkdtemp(join(process.cwd(), 'data-test-'));
  let server;
  try {
    const databasePath = join(directory, 'nested', 'projects.sqlite');
    server = await startServer(databasePath);
    const health = await fetch(`${server.url}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });

    const initial = await (await fetch(server.url)).text();
    assert.match(initial, /<h1>Workboard<\/h1>/);
    assert.match(initial, /<label for="project-name">Project name<\/label>/);
    assert.match(initial, />Create project<\/button>/);
    assert.doesNotMatch(initial, /data-testid="project-row"/);

    const create = name => fetch(`${server.url}/projects`, {
      method: 'POST', body: new URLSearchParams({ name }), redirect: 'manual',
    });
    for (const name of ['', ' \t\n ']) {
      const invalid = await create(name);
      assert.equal(invalid.status, 400);
      const html = await invalid.text();
      assert.match(html, /role="alert">Project name is required/);
      assert.doesNotMatch(html, /data-testid="project-row"/);
    }
    const created = await create('  First project  ');
    assert.equal(created.status, 303);
    assert.equal(created.headers.get('location'), '/');
    await create('Second <script>alert("x")</script> & project');
    const list = await (await fetch(server.url)).text();
    assert.equal((list.match(/data-testid="project-row"/g) ?? []).length, 2);
    assert.match(list, /<span>First project<\/span>/);
    assert.match(list, /Second &lt;script&gt;alert\(&quot;x&quot;\)&lt;\/script&gt; &amp; project/);
    assert.ok(list.indexOf('First project') < list.indexOf('Second'));
    const projectPath = /action="(\/projects\/\d+)"/.exec(list)[1];
    const detail = await (await fetch(`${server.url}${projectPath}`)).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/".*>Projects<\/button>/);
    assert.equal((await fetch(`${server.url}/projects/99999`)).status, 404);

    assert.match(detail, /<label for="task-title">Task title<\/label>/);
    assert.match(detail, />Create task<\/button>/);
    assert.match(detail, /<label for="task-filter">Task filter<\/label>/);
    assert.match(detail, /<option value="all" selected>All<\/option>/);
    const createTask = (title, path = projectPath) => fetch(`${server.url}${path}/tasks`, {
      method: 'POST', body: new URLSearchParams({ title }), redirect: 'manual',
    });
    const taskCount = html => (html.match(/data-testid="task-row"/g) ?? []).length;
    const readProject = (query = '') => fetch(`${server.url}${projectPath}${query}`).then(response => response.text());
    for (const title of ['', ' \t\n ']) {
      const invalid = await createTask(title);
      assert.equal(invalid.status, 400);
      const html = await invalid.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.equal(taskCount(html), 0);
    }
    const firstTask = await createTask('  First task  ');
    assert.equal(firstTask.status, 303);
    assert.equal(firstTask.headers.get('location'), projectPath);
    await createTask('Second <script> & "task"');
    const tasks = await readProject();
    assert.equal(taskCount(tasks), 2);
    assert.match(tasks, /<span>First task<\/span>/);
    assert.match(tasks, /aria-label="Complete First task"/);
    assert.match(tasks, /Second &lt;script&gt; &amp; &quot;task&quot;/);
    assert.ok(tasks.indexOf('<span>First task') < tasks.indexOf('<span>Second'));
    assert.doesNotMatch(tasks, / checked/);
    assert.equal(taskCount(await readProject('?filter=open')), 2);
    assert.equal(taskCount(await readProject('?filter=completed')), 0);
    const taskPath = /action="([^" ]+\/tasks\/\d+)"/.exec(tasks)[1];
    const setCompletion = (completed, filter = 'all', path = taskPath) => fetch(`${server.url}${path}`, {
      method: 'POST',
      body: new URLSearchParams({ ...(completed ? { completed: '1' } : {}), filter }),
      redirect: 'manual',
    });
    const complete = await setCompletion(true, 'open');
    assert.equal(complete.status, 303);
    assert.equal(complete.headers.get('location'), `${projectPath}?filter=open`);
    assert.match(await readProject(), /aria-label="Complete First task" checked/);
    const openTasks = await readProject('?filter=open');
    assert.equal(taskCount(openTasks), 1);
    assert.doesNotMatch(openTasks, /<span>First task/);
    const completedTasks = await readProject('?filter=completed');
    assert.equal(taskCount(completedTasks), 1);
    assert.match(completedTasks, /<span>First task/);
    assert.match(completedTasks, /value="completed" selected/);
    assert.equal(taskCount(await readProject('?filter=invalid')), 2);

    const secondPath = [...list.matchAll(/action="(\/projects\/\d+)"/g)][1][1];
    assert.equal(taskCount(await (await fetch(`${server.url}${secondPath}`)).text()), 0);
    assert.equal((await createTask('Other project task', secondPath)).status, 303);
    const otherTasks = await (await fetch(`${server.url}${secondPath}`)).text();
    assert.equal(taskCount(otherTasks), 1);
    assert.doesNotMatch(otherTasks, /<span>First task|<span>Second &lt;/);
    assert.equal((await setCompletion(false, 'all', taskPath.replace(projectPath, secondPath))).status, 404);
    assert.equal((await createTask('Missing', '/projects/99999')).status, 404);
    assert.equal((await setCompletion(true, 'all', `${projectPath}/tasks/99999`)).status, 404);
    await setCompletion(false);
    assert.equal(taskCount(await readProject('?filter=completed')), 0);
    assert.equal(taskCount(await readProject('?filter=open')), 2);
    await setCompletion(true);
    const savedDetail = await readProject();
    const savedList = await (await fetch(server.url)).text();

    await server.stop();
    server = await startServer(databasePath);
    const restored = await (await fetch(server.url)).text();
    assert.equal(restored, savedList);
    assert.equal(await readProject(), savedDetail);
    assert.equal(await readProject('?filter=completed'), completedTasks);
    assert.equal(await (await fetch(`${server.url}${secondPath}`)).text(), otherTasks);
    await setCompletion(false);
    assert.equal(taskCount(await readProject('?filter=completed')), 0);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});


